Here's a modern MSTest data-driven test class for your `PriceCalculator`:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator = new();

    // --- CalculateTotal: DataRow for inline combinations ---

    [TestMethod]
    [DataRow(10.00, 2, 0.10, 22.00, DisplayName = "Standard tax")]
    [DataRow(5.00, 1, 0.0, 5.00, DisplayName = "Zero tax")]
    [DataRow(99.99, 0, 0.25, 0.00, DisplayName = "Zero quantity")]
    [DataRow(0.00, 5, 0.10, 0.00, DisplayName = "Zero price")]
    [DataRow(15.50, 3, 0.20, 55.80, DisplayName = "20% tax")]
    public void CalculateTotal_ValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);
        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1.00, 2, 0.10, "unitPrice", DisplayName = "Negative price")]
    [DataRow(10.00, -1, 0.10, "quantity", DisplayName = "Negative quantity")]
    [DataRow(10.00, 2, -0.01, "taxRate", DisplayName = "Negative tax")]
    [DataRow(10.00, 2, 1.01, "taxRate", DisplayName = "Tax > 1")]
    public void CalculateTotal_InvalidInput_ThrowsArgumentOutOfRange(
        double unitPrice, int quantity, double taxRate, string expectedParam)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
        Assert.AreEqual(expectedParam, ex.ParamName);
    }

    // --- ApplyDiscount: DynamicData with ValueTuples for type safety ---

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_ValidInputs_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);
        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, decimal discountPercent, decimal expected)> DiscountTestData =>
    [
        (100m, 10m, 90m),
        (200m, 25m, 150m),
        (50m, 0m, 50m),
        (80m, 100m, 0m),
        (99.99m, 50m, 49.995m),
    ];

    [TestMethod]
    [DataRow(-1.0, DisplayName = "Negative discount")]
    [DataRow(101.0, DisplayName = "Discount > 100")]
    public void ApplyDiscount_InvalidPercent_ThrowsArgumentOutOfRange(double discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, (decimal)discountPercent));
    }
}
```

**Key patterns demonstrated:**

| Technique | Why |
|---|---|
| `sealed` class | Performance + design clarity |
| Constructor init (`new()`) | Enables `readonly`, no `[TestInitialize]` needed for sync setup |
| `[DataRow]` with `DisplayName` | Inline data, clear test names in explorer |
| `DynamicData` + ValueTuples | Type-safe complex data without `object[]` casts (MSTest 3.7+) |
| `Assert.ThrowsExactly<T>` | Replaces `[ExpectedException]`; lets you verify `ParamName` |
| `Assert.AreEqual(expected, actual)` | Correct arg order (expected first) |

> **Note:** `[DataRow]` doesn't support `decimal` literals directly — use `double` params and cast inside the method. `DynamicData` has no such limitation, making it ideal for decimal-heavy scenarios.
